import{_ as t,c as a,o,aA as i}from"./chunks/framework.C0-mzrGA.js";const n="/MaterialPointSolver.jl/v0.4.6/assets/mpmprocess.B5bRf_Vr.png",r="/MaterialPointSolver.jl/v0.4.6/assets/knife.CVf2tYRe.png",f=JSON.parse('{"title":"Why?","description":"","frontmatter":{},"headers":[],"relativePath":"introduction/why.md","filePath":"introduction/why.md","lastUpdated":null}'),s={name:"introduction/why.md"};function l(c,e,d,p,h,m){return o(),a("div",null,e[0]||(e[0]=[i('<h1 id="why" tabindex="-1">Why? <a class="header-anchor" href="#why" aria-label="Permalink to &quot;Why?&quot;">​</a></h1><p>This project began as a research initiative where we aimed to study the run-out process of landslides after instability through numerical simulations. However, this nonlinear large deformation problem is difficult to address using mesh-based methods because the mesh can become distorted. At this point, the Material Point Method (MPM), which combines a Lagrangian perspective with an Eulerian perspective, will be quite advantageous for this type of problem.</p><p><img src="'+n+'" alt=""></p><p>However, MPM does not have as many available software/codes as FEM, and there is also less work focused on computational performance. Notable examples include Anura3D, which is written in Fortran, and CB-Geo MPM, which is written in C++. Installing, configuring, and using these libraries is not easy. We hope to leverage the advantages of the Julia language to allow users to install with one click and achieve better performance.</p><p>These software and code, due to being written a long time ago, are no longer compatible with the rapidly developing computing resources of today. Currently, we mainly utilize the powerful performance of GPUs, and it is important to note that GPU vendors are not limited to NVIDIA. In this case, whether as researchers or related professionals, it would be a fantastic experience if we could write just one set of code that can run on different backends.</p><p>For these reasons, we have implemented <em><strong>MaterialPointSolver.jl</strong></em>. I personally believe that its design coincidentally follows Victorinox&#39;s design principle: &quot;design follows function.&quot; We develop new features driven by practical problems. Aside from its excellent performance, we try to choose simple implementation methods (a trade-off between performance and code readability), and it is very convenient to add custom features at any level, just like purchasing a Swiss Army Knife™, supporting personalization.</p><div align="center"><img src="'+r+'" width="50%"></div>',7)]))}const w=t(s,[["render",l]]);export{f as __pageData,w as default};
